<?php
$path=sys_get_temp_dir().'/staff-management-'.bin2hex(random_bytes(5)).'.sqlite';putenv('APP_DSN=sqlite:'.$path);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/actions.php';db()->exec(file_get_contents(__DIR__.'/../src/schema.sql'));require __DIR__.'/../bin/migrate.php';
$n=0;function assertStaff(bool $ok,string $msg):void{global $n;if(!$ok)throw new RuntimeException($msg);$n++;}
function rejectStaff(callable $fn,string $msg):void{$failed=false;db()->beginTransaction();try{$fn();}catch(RuntimeException $e){$failed=true;}finally{db()->rollBack();}assertStaff($failed,$msg);}
foreach(['admin','hod','pl','daa','faculty']as $role)q('INSERT INTO users(name,email,password,role,department) VALUES(?,?,?,?,?)',[$role,$role.'@test.bt',password_hash('Password12345!',PASSWORD_DEFAULT),$role,departments()[0]]);
$users=[];foreach(all('SELECT * FROM users')as $u)$users[$u['role']]=$u;
$fid=(int)$users['faculty']['id'];$admin=$users['admin'];
$p=['id'=>$fid,'name'=>'Adjunct Example','email'=>'faculty@test.bt','role'=>'faculty','department'=>departments()[0],'active'=>'1','teaching_enabled'=>'1','staff_type'=>'Adjunct','status_reason'=>'Semester appointment'];
db()->beginTransaction();saveStaffAccount($admin,$p);db()->commit();assertStaff(staffProfile($fid)['staff_type']==='Adjunct','adjunct saved independently of role');
function requestFixture(int $fid,string $status='Pending HoD/PL'):int{q('INSERT INTO requests(module,applicant_id,department,status,payload,created_at,updated_at) VALUES(?,?,?,?,?,?,?)',['substitution',$fid,departments()[0],$status,'{}',now(),now()]);return (int)db()->lastInsertId();}
$id=requestFixture($fid);$r=one('SELECT * FROM requests WHERE id=?',[$id]);assertStaff(approvalStages($r)['HoD']['status']==='Pending'&&approvalStages($r)['DAA']['status']==='Pending','initial stages pending');
rejectStaff(fn()=>transition($users['daa'],$id,'Pending DAA',''),'DAA cannot approve as HoD');rejectStaff(fn()=>transition($users['daa'],$id,'Rejected by HoD/PL','No'),'DAA cannot reject as HoD');rejectStaff(fn()=>transition($users['pl'],$id,'Pending DAA',''),'PL cannot perform HoD decision');
$other=$users['hod'];$other['department']=departments()[1];rejectStaff(fn()=>transition($other,$id,'Pending DAA',''),'wrong department HoD denied');
db()->beginTransaction();transition($users['hod'],$id,'Pending DAA','Reviewed');db()->commit();$r=one('SELECT * FROM requests WHERE id=?',[$id]);$stages=approvalStages($r);assertStaff($stages['HoD']['status']==='Approved'&&$stages['HoD']['name']==='hod'&&$stages['HoD']['date']!=='—','HoD approval actor and date retained');assertStaff($stages['DAA']['status']==='Pending','DAA remains pending after HoD');
$daa=$users['daa'];$daa['department']=departments()[1];assertStaff(canView($daa,$r),'DAA views cross department request');db()->beginTransaction();transition($daa,$id,'Approved','Final');db()->commit();$r=one('SELECT * FROM requests WHERE id=?',[$id]);assertStaff(approvalStages($r)['DAA']['status']==='Approved','cross department DAA final approval');
$rejected=requestFixture($fid);db()->beginTransaction();transition($users['hod'],$rejected,'Rejected by HoD/PL','Insufficient information');db()->commit();$stages=approvalStages(one('SELECT * FROM requests WHERE id=?',[$rejected]));assertStaff($stages['HoD']['status']==='Rejected'&&$stages['DAA']['status']==='Pending','HoD rejection does not become DAA rejection');rejectStaff(fn()=>transition($daa,$rejected,'Approved',''),'DAA cannot approve HoD rejection');
$pending=requestFixture($fid);$oldCount=(int)q('SELECT COUNT(*) FROM history')->fetchColumn();$p['department']=departments()[1];db()->beginTransaction();saveStaffAccount($admin,$p);db()->commit();assertStaff(one('SELECT department FROM requests WHERE id=?',[$pending])['department']===departments()[1],'transfer reroutes pending HoD request');assertStaff(one('SELECT department FROM requests WHERE id=?',[$id])['department']===departments()[0],'transfer preserves completed historical department');assertStaff((int)q('SELECT COUNT(*) FROM history')->fetchColumn()>$oldCount,'transfer audited');rejectStaff(fn()=>transition($users['hod'],$pending,'Pending DAA',''),'old department cannot approve after transfer');
db()->beginTransaction();setStaffStatus($admin,$fid,false,'Semester ended');db()->commit();assertStaff(!in_array($fid,array_column(staff(),'id')),'inactive staff excluded from dropdown source');assertStaff(staffProfile($fid)['staff_type']==='Adjunct','disable preserves adjunct type');rejectStaff(fn()=>publicApplicant(['module'=>'substitution','applicant_id'=>$fid,'applicant_email'=>'faculty@test.bt']),'inactive staff rejected on new request');assertStaff((bool)one('SELECT id FROM requests WHERE id=?',[$id]),'disable retains previous request');assertStaff(count(filteredStaff(['staff_search'=>'Adjunct','staff_department'=>departments()[1],'staff_status'=>'Inactive']))===1,'name department and inactive search');
db()->beginTransaction();setStaffStatus($admin,$fid,true,'Returned semester 3');db()->commit();assertStaff(in_array($fid,array_column(staff(),'id')),'reactivation restores same staff to dropdown');assertStaff((int)q('SELECT COUNT(*) FROM users')->fetchColumn()===5,'no duplicate staff created');assertStaff(approvalStages(one('SELECT * FROM requests WHERE id=?',[$id]))['DAA']['status']==='Approved','reactivation retains approval evidence');
rejectStaff(fn()=>setStaffStatus($users['hod'],$fid,false),'nonadmin status change denied');rejectStaff(fn()=>setStaffStatus($admin,(int)$admin['id'],false),'self disable denied');
$ids=[$fid,(int)$users['hod']['id'],(int)$users['daa']['id']];
db()->beginTransaction();$changed=bulkTeachingAttendance($admin,['staff_ids'=>$ids,'enabled'=>'1']);db()->commit();assertStaff($changed===3,'bulk enable counts selected faculty and officials');foreach($ids as $id)assertStaff(teaching(one('SELECT * FROM users WHERE id=?',[$id])),'bulk enabled selected staff');assertStaff(one('SELECT role FROM users WHERE id=?',[$users['hod']['id']])['role']==='hod','bulk does not alter official role');
rejectStaff(fn()=>bulkTeachingAttendance($users['hod'],['staff_ids'=>$ids,'enabled'=>'0']),'nonadmin cannot bulk edit');rejectStaff(fn()=>bulkTeachingAttendance($admin,['staff_ids'=>[],'enabled'=>'1']),'empty bulk selection rejected');
db()->beginTransaction();bulkTeachingAttendance($admin,['staff_ids'=>$ids,'enabled'=>'0']);db()->commit();assertStaff(!teaching(one('SELECT * FROM users WHERE id=?',[$fid]))&&one('SELECT active FROM users WHERE id=?',[$fid])['active']==1,'bulk attendance disabled while account remains active');
unlink($path);echo "$n staff-management and approval checks passed.\n";
